{
  "name": "snow-globe",
  "version": "1.0.0",
  "type": "module",
  "description": "Snow-globe ornament: particles confined to a glass dome",
  "main": "src/snowglobe.js",
  "scripts": {
    "test": "vitest run"
  },
  "keywords": ["three", "snowglobe", "particles"],
  "license": "MIT"
}

import * as THREE from 'three';

/** Small, fast seeded PRNG (mulberry32). Returns floats in [0, 1). */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const MARGIN = 0.05; // flakes must stay inside domeRadius - MARGIN

/**
 * Rejection-sample a point uniformly inside the sphere of given radius.
 * Uses the provided rng so results are deterministic per seed.
 */
function sampleInSphere(rng, radius) {
  for (;;) {
    const x = rng() * 2 - 1;
    const y = rng() * 2 - 1;
    const z = rng() * 2 - 1;
    if (x * x + y * y + z * z <= radius * radius) {
      return [x * radius, y * radius, z * radius];
    }
  }
}

/**
 * Rejection-sample a point uniformly inside the upper half of the sphere
 * (y >= 0), i.e. inside the glass dome sitting on the base.
 */
function sampleInDome(rng, radius) {
  for (;;) {
    const p = sampleInSphere(rng, radius);
    if (p[1] >= 0) return p;
  }
}

/**
 * Build the snow globe scene graph.
 *
 * @param {object} [opts]
 * @param {number} [opts.domeRadius=4] - radius of the glass dome
 * @param {number} [opts.flakes=300]   - number of snow particles
 * @param {number} [opts.seed=1]       - seed for all randomness
 * @returns {{
 *   group: THREE.Group,
 *   base: THREE.Mesh,
 *   dome: THREE.Mesh,
 *   points: THREE.Points,
 *   positions: Float32Array,
 *   domeRadius: number,
 *   flakes: number,
 *   seed: number,
 *   driftX: Float32Array,
 *   driftZ: Float32Array,
 *   rng: () => number,
 *   respawns: number
 * }}
 */
export function buildGlobe({ domeRadius = 4, flakes = 300, seed = 1 } = {}) {
  const rng = mulberry32(seed);
  const group = new THREE.Group();

  // --- Base: solid cylinder under the dome -------------------------------
  const baseHeight = domeRadius * 0.35;
  const base = new THREE.Mesh(
    new THREE.CylinderGeometry(domeRadius * 0.95, domeRadius, baseHeight, 48)
  );
  base.position.y = -baseHeight / 2; // top of base sits at y = 0
  group.add(base);

  // --- Glass dome: hemisphere --------------------------------------------
  const dome = new THREE.Mesh(
    new THREE.SphereGeometry(
      domeRadius,
      48,
      24,
      0,
      Math.PI * 2,
      0,
      Math.PI / 2 // upper hemisphere only
    )
  );
  group.add(dome);

  // --- Snow: Points cloud with positions inside the dome -----------------
  const positions = new Float32Array(flakes * 3);
  const driftX = new Float32Array(flakes);
  const driftZ = new Float32Array(flakes);

  for (let i = 0; i < flakes; i++) {
    const [x, y, z] = sampleInDome(rng, domeRadius - MARGIN);
    positions[i * 3 + 0] = x;
    positions[i * 3 + 1] = y;
    positions[i * 3 + 2] = z;

    // Seeded per-flake horizontal drift
    driftX[i] = (rng() * 2 - 1) * 0.3;
    driftZ[i] = (rng() * 2 - 1) * 0.3;
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const material = new THREE.PointsMaterial({
    color: 0xffffff,
    size: 0.06,
    sizeAttenuation: true,
  });
  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;
  group.add(points);

  return {
    group,
    base,
    dome,
    points,
    positions,
    domeRadius,
    flakes,
    seed,
    driftX,
    driftZ,
    rng,
    respawns: 0,
  };
}

/**
 * Advance the snow simulation by dt seconds.
 *
 * Each flake falls at speed 0.5 plus its seeded horizontal drift. Any flake
 * that leaves the dome (|p| > domeRadius - 0.05 or y < 0) respawns at a
 * seeded position in the upper half of the dome. g.respawns counts every
 * respawn event.
 */
export function stepSnow(g, dt) {
  const { positions, driftX, driftZ, domeRadius } = g;
  const limit = domeRadius - MARGIN;
  const limitSq = limit * limit;
  const respawnRadius = limit * 0.8;

  for (let i = 0; i < g.flakes; i++) {
    const o = i * 3;
    positions[o + 1] -= 0.5 * dt; // fall speed
    positions[o + 0] += driftX[i] * dt;
    positions[o + 2] += driftZ[i] * dt;

    const x = positions[o + 0];
    const y = positions[o + 1];
    const z = positions[o + 2];

    if (y < 0 || x * x + y * y + z * z > limitSq) {
      // Respawn at a seeded position in the upper half of the dome.
      const [rx, ry, rz] = sampleInSphere(g.rng, respawnRadius);
      positions[o + 0] = rx;
      positions[o + 1] = respawnRadius * 0.5 + ry * 0.5; // y >= radius/4 > 0
      positions[o + 2] = rz;
      // Keep the full |p| strictly within the containment limit.
      if (
        positions[o] ** 2 +
          positions[o + 1] ** 2 +
          positions[o + 2] ** 2 >
        limitSq
      ) {
        const s =
          limit * 0.99 /
          Math.sqrt(
            positions[o] ** 2 +
              positions[o + 1] ** 2 +
              positions[o + 2] ** 2
          );
        positions[o] *= s;
        positions[o + 1] *= s;
        positions[o + 2] *= s;
      }
      g.respawns++;
    }
  }

  g.points.geometry.attributes.position.needsUpdate = true;
}

