import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildGlobe, stepSnow } from '../src/snowglobe.js';

const DT = 1 / 60;

function contained(x, y, z, domeRadius) {
  const limit = domeRadius - 0.05;
  return Math.sqrt(x * x + y * y + z * z) <= limit && y >= 0;
}

describe('snow globe', () => {
  it('has a position attribute of length flakes*3', () => {
    const g = buildGlobe({ flakes: 300, seed: 42 });
    const attr = g.points.geometry.getAttribute('position');
    expect(attr).toBeInstanceOf(THREE.BufferAttribute);
    expect(attr.count * attr.itemSize).toBe(300 * 3);
    expect(g.positions.length).toBe(300 * 3);
  });

  it('initial flakes are inside the dome and above the base', () => {
    const domeRadius = 4;
    const g = buildGlobe({ domeRadius, flakes: 300, seed: 7 });
    for (let i = 0; i < g.flakes; i++) {
      const x = g.positions[i * 3];
      const y = g.positions[i * 3 + 1];
      const z = g.positions[i * 3 + 2];
      expect(contained(x, y, z, domeRadius)).toBe(true);
      expect(y).toBeGreaterThanOrEqual(0);
    }
  });

  it('keeps every flake contained after 2000 steps of dt=1/60', () => {
    const domeRadius = 4;
    const g = buildGlobe({ domeRadius, flakes: 300, seed: 123 });
    for (let s = 0; s < 2000; s++) stepSnow(g, DT);

    for (let i = 0; i < g.flakes; i++) {
      const x = g.positions[i * 3];
      const y = g.positions[i * 3 + 1];
      const z = g.positions[i * 3 + 2];
      expect(contained(x, y, z, domeRadius)).toBe(true);
    }
  });

  it('respawns at least one flake over the simulation', () => {
    const g = buildGlobe({ flakes: 300, seed: 5 });
    // Long enough that flakes falling at 0.5/s hit the floor (y<0) and respawn.
    for (let s = 0; s < 2000; s++) stepSnow(g, DT);
    expect(g.respawns).toBeGreaterThan(0);
  });

  it('same seed produces identical positions after 100 steps', () => {
    const a = buildGlobe({ flakes: 300, seed: 2024 });
    const b = buildGlobe({ flakes: 300, seed: 2024 });
    for (let s = 0; s < 100; s++) {
      stepSnow(a, DT);
      stepSnow(b, DT);
    }
    expect(Array.from(a.positions)).toEqual(Array.from(b.positions));
  });
});

